    ///
    /// - Parameters:
    ///   - companyID: The company; the client's `companyID` when `nil`.
    ///   - id: id разговора: dialog_id из ответа (заголовок X-Dialog-Id, поле id в списке разговоров). Обычно UUID; клиент мог задать свой (до 64 знаков A–Z, a–z, 0–9, _ и -)
    ///   - body: The request body.
    ///   - options: Per-request options: timeout, retries, extra headers, idempotency key.
    /// - Returns: The decoded response.
    /// - Throws: ``APIError`` for an error response, or another ``TungoError``.
    public func answer(
        companyID: String? = nil,
        id: String,
        body: ChatAnswerRequest,
        options: RequestOptions = RequestOptions()
    ) async throws -> ChatTurnResult {
        try await answerWithResponse(companyID: companyID, id: id, body: body, options: options).value
    }

    /// Ответ на уточняющий вопрос ИИ (событие choice)
    ///
    /// Продолжает ход потоком SSE. Повторный ответ на тот же choice_id — 409 (error.turn — номер хода с ответом; error.code = dismissed — вопрос закрыт без ответа). Отказы: 402 — ИИ компании не подключён (не оплачено подключение); 409 — идёт предыдущий ход или разговор закрыт (error.code = dialog_closed); 410 — разговор не найден или истёк, начните новый; 429 — кончился лимит тарифа; 503 — сервис модели не настроен.
    ///
    /// Доступ: chat.use.
    ///
    /// Доступно по ключу API.
    ///
    /// `POST /v1/companies/{co}/chat/{id}/answer` - permission `chat.use`
    ///
    /// The same call as `answer`, returning the HTTP metadata as well.
    ///
    /// - Parameters:
    ///   - companyID: The company; the client's `companyID` when `nil`.
    ///   - id: id разговора: dialog_id из ответа (заголовок X-Dialog-Id, поле id в списке разговоров). Обычно UUID; клиент мог задать свой (до 64 знаков A–Z, a–z, 0–9, _ и -)
    ///   - body: The request body.
    ///   - options: Per-request options: timeout, retries, extra headers, idempotency key.
    /// - Returns: The decoded response with its status, headers, request id and rate-limit state.
    /// - Throws: ``APIError`` for an error response, or another ``TungoError``.
    public func answerWithResponse(
        companyID: String? = nil,
        id: String,
        body: ChatAnswerRequest,
        options: RequestOptions = RequestOptions()
    ) async throws -> APIResponse<ChatTurnResult> {
        let path = "/v1/companies/" + (try core.companySegment(companyID)) + "/chat/" + (try PercentEncoding.pathSegment(id, name: "id")) + "/answer"
        var spec = RequestSpec(method: "POST", path: path, longRunning: true)
        var body = body
        body.stream = false
        spec.body = try core.encode(body)
        return try await core.send(spec, options: options, as: ChatTurnResult.self)
    }

    /// Ответ на уточняющий вопрос ИИ (событие choice)
    ///
    /// Продолжает ход потоком SSE. Повторный ответ на тот же choice_id — 409 (error.turn — номер хода с ответом; error.code = dismissed — вопрос закрыт без ответа). Отказы: 402 — ИИ компании не подключён (не оплачено подключение); 409 — идёт предыдущий ход или разговор закрыт (error.code = dialog_closed); 410 — разговор не найден или истёк, начните новый; 429 — кончился лимит тарифа; 503 — сервис модели не настроен.
    ///
    /// Доступ: chat.use.
    ///
    /// Доступно по ключу API.
    ///
    /// `POST /v1/companies/{co}/chat/{id}/answer` - permission `chat.use`
    ///
    /// Streams the answer (`stream: true`). The call returns when the response head arrives; `options.timeout` is the idle timeout of the stream.
    ///
    /// - Parameters:
    ///   - companyID: The company; the client's `companyID` when `nil`.
    ///   - id: id разговора: dialog_id из ответа (заголовок X-Dialog-Id, поле id в списке разговоров). Обычно UUID; клиент мог задать свой (до 64 знаков A–Z, a–z, 0–9, _ и -)
    ///   - body: The request body.
    ///   - options: Per-request options: timeout, retries, extra headers, idempotency key.
    /// - Returns: The event stream. Leaving the loop or cancelling the task closes the connection.
    /// - Throws: ``APIError`` for an error response, or another ``TungoError``.
    public func answerStream(
        companyID: String? = nil,
        id: String,
        body: ChatAnswerRequest,
        options: RequestOptions = RequestOptions()
    ) async throws -> EventStream<ChatEvent> {
        let path = "/v1/companies/" + (try core.companySegment(companyID)) + "/chat/" + (try PercentEncoding.pathSegment(id, name: "id")) + "/answer"
        var spec = RequestSpec(method: "POST", path: path)
        var body = body
        body.stream = true
        spec.body = try core.encode(body)
        let response = try await core.openStream(spec, options: options)
        return EventStream(response: response, decoding: ChatEvent.self, errorIsEvent: true)
    }

    /// Переподключиться к идущему ходу
    ///
    /// Переподключение — с заголовком Last-Event-ID: события до него не повторяются. Ход уже сменился (turn не совпал) — 409 с error.turn. Хода нет (закончен и выгружен) — 404: откройте разговор GET …/chat/{id}. Ход идёт на другом сервере Tungo (несколько экземпляров за балансировщиком) — поток из status (code elsewhere) и, когда ход закончится, done со stop_reason elsewhere: ответ тогда — в GET …/chat/{id}.
    ///
    /// Доступ: chat.use.
    ///
    /// Доступно по ключу API.
    ///
    /// `GET /v1/companies/{co}/chat/{id}/events` - permission `chat.use`
    ///
    /// The call returns when the response head arrives; events are then delivered as the server sends them. `options.timeout` is the idle timeout of the stream.
    ///
    /// - Parameters:
    ///   - companyID: The company; the client's `companyID` when `nil`.
    ///   - id: id разговора: dialog_id из ответа (заголовок X-Dialog-Id, поле id в списке разговоров). Обычно UUID; клиент мог задать свой (до 64 знаков A–Z, a–z, 0–9, _ и -)
    ///   - turn: Номер хода (X-Turn-No), к которому переподключиться; без него — к текущему
    ///   - options: Per-request options: timeout, retries, extra headers, idempotency key.
    /// - Returns: The event stream. Leaving the loop or cancelling the task closes the connection.
    /// - Throws: ``APIError`` for an error response, or another ``TungoError``.
    public func listEvents(
        companyID: String? = nil,
        id: String,
        turn: Int? = nil,
        options: RequestOptions = RequestOptions()
    ) async throws -> EventStream<ChatEvent> {
        let path = "/v1/companies/" + (try core.companySegment(companyID)) + "/chat/" + (try PercentEncoding.pathSegment(id, name: "id")) + "/events"
        var query = QueryBuilder()
        query.add("turn", turn)
        let spec = RequestSpec(method: "GET", path: path, query: query)
        let response = try await core.openStream(spec, options: options)
        return EventStream(response: response, decoding: ChatEvent.self, errorIsEvent: true)
    }

    /// Остановить ход или закрыть открытый вопрос
    ///
    /// Идёт ход — останавливается (поток получит ошибку aborted и done). Ход ждёт ответа на вопрос — вопрос закрывается без ответа (dismissed: true). Ни хода, ни вопроса — 404.
    ///
    /// Доступ: chat.use.
    ///
    /// Доступно по ключу API.
    ///
    /// `POST /v1/companies/{co}/chat/{id}/stop` - permission `chat.use`
    ///
    /// - Parameters:
    ///   - companyID: The company; the client's `companyID` when `nil`.
    ///   - id: id разговора: dialog_id из ответа (заголовок X-Dialog-Id, поле id в списке разговоров). Обычно UUID; клиент мог задать свой (до 64 знаков A–Z, a–z, 0–9, _ и -)
    ///   - options: Per-request options: timeout, retries, extra headers, idempotency key.
    /// - Returns: The decoded response.
    /// - Throws: ``APIError`` for an error response, or another ``TungoError``.
    public func stop(companyID: String? = nil, id: String, options: RequestOptions = RequestOptions()) async throws -> ChatStopResult {
        try await stopWithResponse(companyID: companyID, id: id, options: options).value
    }

    /// Остановить ход или закрыть открытый вопрос
    ///
    /// Идёт ход — останавливается (поток получит ошибку aborted и done). Ход ждёт ответа на вопрос — вопрос закрывается без ответа (dismissed: true). Ни хода, ни вопроса — 404.
    ///
    /// Доступ: chat.use.
    ///
    /// Доступно по ключу API.
    ///
    /// `POST /v1/companies/{co}/chat/{id}/stop` - permission `chat.use`
    ///
    /// The same call as `stop`, returning the HTTP metadata as well.
    ///
    /// - Parameters:
    ///   - companyID: The company; the client's `companyID` when `nil`.
    ///   - id: id разговора: dialog_id из ответа (заголовок X-Dialog-Id, поле id в списке разговоров). Обычно UUID; клиент мог задать свой (до 64 знаков A–Z, a–z, 0–9, _ и -)
    ///   - options: Per-request options: timeout, retries, extra headers, idempotency key.
    /// - Returns: The response with its status, headers, request id and rate-limit state.
    /// - Throws: ``APIError`` for an error response, or another ``TungoError``.
    public func stopWithResponse(
        companyID: String? = nil,
        id: String,
        options: RequestOptions = RequestOptions()
    ) async throws -> APIResponse<ChatStopResult> {
        let path = "/v1/companies/" + (try core.companySegment(companyID)) + "/chat/" + (try PercentEncoding.pathSegment(id, name: "id")) + "/stop"
        let spec = RequestSpec(method: "POST", path: path)
        return try await core.send(spec, options: options, as: ChatStopResult.self)
    }
}
